{/if}
{if ui_t(ui_eq($v_value, 'no'))}
  {capture $c_4}
    {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'minus', 'Size' => 16]])|noescape}
    {capture $c_3}
