    {/capture}
    {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'sr-only'], 'children' => $c_3])|noescape}
  {/capture}
  {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'inline-flex items-center gap-2 text-muted-foreground', 'Attrs' => ui_attrs(['data-mark', 'no'])], 'children' => $c_4])|noescape}
{/if}
{if ui_t(ui_and([!(ui_eq($v_value, 'yes')), !(ui_eq($v_value, 'no'))]))}
  {capture $c_5}
    {=ui_text($v_value)}
  {/capture}
  {=ui_include('ui/inline/inline.latte', ['p' => [], 'children' => $c_5])|noescape}
{/if}
